package com.mendes.scheduling_platform.venue; import com.mendes.scheduling_platform.security.TenantContext; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/venues") public class VenueController { private final VenueService s; public VenueController(VenueService s){this.s=s;} @GetMapping List<Venue> list(){return s.list(TenantContext.getRequired());}@GetMapping("/{id}") Venue get(@PathVariable Long id){return s.get(TenantContext.getRequired(),id);}@PostMapping Venue add(@RequestBody Venue v){return s.save(TenantContext.getRequired(),v);}@PutMapping("/{id}") Venue edit(@PathVariable Long id,@RequestBody Venue v){return s.update(TenantContext.getRequired(),id,v);}@DeleteMapping("/{id}") void delete(@PathVariable Long id){s.delete(TenantContext.getRequired(),id);} }
